import {exampleEvents,walkthroughDecisions,walkthroughJudge,defaultPolicy} from './fixtures.js';
import {normalizeEvent,normalizeContexts,validateDecision,validateJudge,retrievalMetrics,summarize,validateServiceURL,safeExport} from './evaluation.js';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={flow:'M4 5h5v5H4zM15 14h5v5h-5zM15 3h5v5h-5zM9 7.5h3v9h3M12 5.5h3',stack:'m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5',chart:'M4 20V4M4 20h17M8 16v-5M13 16V7M18 16V4',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',plug:'M8 3v5M16 3v5M6 8h12v4a6 6 0 0 1-12 0V8Zm6 10v4',code:'m8 7-5 5 5 5m8-10 5 5-5 5M14 4l-4 16',motion:'M3 9v6m4-9v12m5-15v18m5-15v12m4-9v6',chevron:'m9 5 7 7-7 7',play:'m8 4 12 8-12 8V4Z',arrow:'M4 12h16m-6-6 6 6-6 6',beaker:'M9 3h6M10 3v7L4 20h16l-6-10V3M7 15h10',settings:'M4 7h16M4 17h16M8 4v6M16 14v6',shield:'m12 3 8 4v5c0 5-8 9-8 9s-8-4-8-9V7l8-4Zm-4 9 3 3 5-6',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5V10Zm7 4v3',doc:'M6 3h8l4 4v14H6V3Zm8 0v5h4M9 12h6m-6 4h6',cpu:'M7 7h10v10H7V7ZM9 3v4m6-4v4M9 17v4m6-4v4M3 9h4m-4 6h4m10-6h4m-4 6h4',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-4 0a5 5 0 1 1-10 0 5 5 0 0 1 10 0ZM12 10v4m-2-2h4',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',refresh:'M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5m-4 8a8 8 0 0 0 14 3l3-3m0 5v-5h-5',bolt:'m13 2-9 12h7l-1 8L21 9h-8l0-7Z',activity:'M2 12h4l3-8 6 16 3-8h4',alert:'m12 3 10 18H2L12 3Zm0 6v5m0 3v1',search:'m16 16 5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.activity}"/></svg>`;
function icons(root=document){$$('[data-icon]',root).forEach(el=>el.innerHTML=icon(el.dataset.icon));}
let stored={};try{stored=JSON.parse(localStorage.getItem('axiom-ems-settings-v1')||'{}');}catch{}
const config={dataSource:stored.dataSource==='ems'?'ems':'example',emsURL:stored.emsURL||'',ragasURL:stored.ragasURL||'',classifierModel:stored.classifierModel||'gpt-4.1-mini',judgeModel:stored.judgeModel||'gpt-4.1-mini',policy:stored.policy||defaultPolicy,topK:5,limit:6,sources:['Zenity','Troj'],mode:'rerun',judge:true,ragas:false,confidenceThreshold:.7};
const secrets={apiKey:'',emsToken:'',ragasToken:''};
let configExpanded=false,scanTick=0,scanContextID='';
let page='pipeline',events=exampleEvents.map(normalizeEvent),selectedID=events[0].id,currentRun=null,running=false,controller=null,elapsedTimer=null,dialogFocus=null,history=[],eventSearch='',eventFilter='all',toastTimer,connectionVerified=false;
let reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;try{reducedMotion=reducedMotion||localStorage.getItem('axiom-reduce-motion')==='true';}catch{}
let flowState={stage:'idle',index:0,completed:0,total:events.length,contexts:[],eventID:null},logs=[];
const labels={pipeline:'Evaluation pipeline',events:'Event queue',results:'Evaluation results',history:'Run history'};
const pct=(v,dec=0)=>Number.isFinite(v)?`${(v*100).toFixed(dec)}%`:'—';
const num=v=>Number.isFinite(v)?v.toFixed(2):'—';
const stateText=r=>r?.error?'Error':r?.evaluationError||r?.decision?.insufficient_evidence||r?.decision?.confidence<r?.threshold?'Review':r?.decision?.verdict||'Queued';
function selectedEvents(){return events.filter(e=>config.sources.includes(e.source)).slice(0,config.limit);}
function getResult(id){return currentRun?.results.find(r=>r.event.id===id);}
function currentEvent(){return events.find(e=>e.id===(flowState.eventID||selectedID))||events[0];}
function selectedContext(){const e=currentEvent();return flowState.contexts.length?flowState.contexts:(getResult(e?.id)?.contexts||e?.contexts||[]).slice(0,config.topK);}
function saveSettings(){try{localStorage.setItem('axiom-ems-settings-v1',JSON.stringify({dataSource:config.dataSource,emsURL:config.emsURL,ragasURL:config.ragasURL,classifierModel:config.classifierModel,judgeModel:config.judgeModel,policy:config.policy}));}catch{}}
function setMotion(){document.body.classList.toggle('reduced-motion',reducedMotion);$('#motion-button').setAttribute('aria-pressed',String(reducedMotion));$('#motion-button').setAttribute('aria-label',reducedMotion?'Enable motion':'Pause motion');if($('#scanner-motion-label'))$('#scanner-motion-label').textContent=reducedMotion?'Resume motion':'Pause motion';}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function announce(message){$('#run-announcement').textContent=message;}
function statusClass(r){const text=stateText(r);return text==='Review'?'review':text==='Error'?'error':text==='TP'?'tp':text==='FP'?'fp':'';}
function configPanel(){return `<section class="panel config-panel ${configExpanded?'expanded':''}"><div class="config-title"><h2>Run configuration</h2><button class="config-toggle quiet" data-action="toggle-config" aria-expanded="${configExpanded}">Configure ${icon('settings')}</button><span class="desktop-config-icon">${icon('settings')}</span></div><div class="config-group"><div class="step-heading"><span>01</span> Event source</div><div class="field"><label for="data-source">Environment</label><select id="data-source" ${running?'disabled':''}><option value="example" ${config.dataSource==='example'?'selected':''}>Example events</option><option value="ems" ${config.dataSource==='ems'?'selected':''}>Connected EMS</option></select></div><div class="sources">${['Zenity','Troj'].map(s=>`<label class="source-toggle"><input type="checkbox" name="source" value="${s}" ${config.sources.includes(s)?'checked':''} ${running?'disabled':''}>${s}</label>`).join('')}</div><div class="field" style="margin-top:13px;margin-bottom:0"><label for="batch-limit">Events per run</label><select id="batch-limit" ${running?'disabled':''}>${[6,12,25,50].map(n=>`<option ${config.limit===n?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="config-group"><div class="step-heading"><span>02</span> Retrieval & decision</div><div class="range-label"><label for="top-k">Context chunks · top K</label><strong id="k-value">${config.topK.toString().padStart(2,'0')}</strong></div><input id="top-k" aria-label="Top K retrieval" type="range" min="1" max="10" value="${config.topK}" ${running?'disabled':''}><div class="range-limits"><span>01</span><span>05</span><span>10</span></div><div class="field" style="margin-top:15px"><label for="run-mode">Decision input</label><select id="run-mode" ${running?'disabled':''}><option value="rerun" ${config.mode==='rerun'?'selected':''}>Re-run OpenAI classifier</option><option value="existing" ${config.mode==='existing'?'selected':''}>Evaluate EMS decisions</option></select><small>${config.mode==='existing'?'Uses the original decision and its original contexts.':'Reference labels stay hidden from the classifier.'}</small></div><div class="field"><label>Classifier model</label><button class="button ghost small" data-action="connections" style="justify-content:space-between">${escapeHTML(config.classifierModel)} ${icon('settings')}</button></div></div><div class="config-group"><div class="step-heading"><span>03</span> Evaluation checks</div><label class="option"><input id="judge-enabled" type="checkbox" ${config.judge?'checked':''} ${running?'disabled':''}><span>LLM retrieval + grounding<small>Relevance, sufficiency & claim support</small></span></label><label class="option"><input id="ragas-enabled" type="checkbox" ${config.ragas?'checked':''} ${running?'disabled':''}><span>Native RAGAS metrics<small>Faithfulness, recall & answer factuality</small></span></label><label class="option"><input type="checkbox" checked disabled><span>Analyst-label comparison<small>Precision, recall, F1 · labelled events only</small></span></label><div class="engine-note">${config.ragas?'<b>RAGAS Python runner</b><br>Connect the runner in service settings.':config.judge?'<b>OpenAI judge</b><br>Context quality and groundedness use custom judge checks. RAGAS scores are shown separately.':'<b>Analyst-label comparison</b><br>Classification metrics are calculated locally from your confirmed labels.'}</div></div><div class="config-footer">${icon('lock')} Keys stay in this session only</div></section>`;}
function pipelineDiagram(){const count=selectedEvents().length,docs=selectedContext();return `<section class="panel pipeline-panel" aria-label="Live event evaluation pipeline"><div class="panel-heading"><div><h2>Evaluation pipeline</h2><p id="pipeline-subtitle">Event → evidence → decision → evaluation</p></div><span class="status-pill" id="pipeline-badge"><i></i>AWAITING RUN</span></div><div class="flow-visual" id="flow-visual" data-stage="idle"><svg class="flow-lines desktop-flow" viewBox="0 0 1000 310" preserveAspectRatio="none" aria-hidden="true"><path class="base" d="M140 91H188Q210 91 210 112V143Q210 155 230 155H288M140 165H190Q210 165 210 155H288M411 155H482M725 155H785Q800 155 800 132V88H860M800 155V169H860M622 232V264H958"/><path class="signal retrieve source-zenity" d="M140 91H188Q210 91 210 112V143Q210 155 230 155H288"/><path class="signal retrieve source-troj" d="M140 165H190Q210 165 210 155H288"/><path class="signal classify" d="M411 155H482"/><path class="signal evaluate complete verdict-tp" d="M725 155H785Q800 155 800 132V88H860"/><path class="signal evaluate complete verdict-fp" d="M725 155H785Q800 155 800 169H860"/></svg><svg class="flow-lines mobile-flow" viewBox="0 0 300 370" preserveAspectRatio="none" aria-hidden="true"><path class="base" d="M65 40V95M230 40V76H65V95M117 160H155M230 227V274H65V305M230 274V305"/><path class="signal retrieve source-zenity" d="M65 40V95"/><path class="signal retrieve source-troj" d="M230 40V76H65V95"/><path class="signal classify" d="M117 160H155"/><path class="signal evaluate complete verdict-tp" d="M230 227V274H65V305"/><path class="signal evaluate complete verdict-fp" d="M230 227V305"/></svg><div class="flow-group flow-sources"><div class="source-node"><span class="source-logo">Z</span><div><b>Zenity</b><small id="zenity-count">${selectedEvents().filter(e=>e.source==='Zenity').length} EVENTS</small></div></div><div class="source-node troj-node"><span class="source-logo troj">T</span><div><b>Troj</b><small id="troj-count">${selectedEvents().filter(e=>e.source==='Troj').length} EVENTS</small></div></div><div class="node-label">01 / INGEST<b>Event feed</b></div></div><div class="flow-group flow-retrieval"><div class="retrieval-stack" id="retrieval-stack">${docStack(docs)}</div><div class="node-label">02 / RETRIEVE<b id="retrieval-label">Top ${config.topK} evidence</b></div></div><div class="flow-group flow-engine"><div class="engine-orbit"><svg class="orbit-svg" viewBox="0 0 200 200" aria-hidden="true"><circle class="orbit-track" cx="100" cy="100" r="88"/><circle class="orbit-track" cx="100" cy="100" r="78" stroke-dasharray="1 8"/>${Array.from({length:48},(_,i)=>{const a=i*Math.PI/24;return `<line class="orbit-ticks" x1="${100+Math.cos(a)*97}" y1="${100+Math.sin(a)*97}" x2="${100+Math.cos(a)*100}" y2="${100+Math.sin(a)*100}"/>`;}).join('')}<circle class="orbit-progress" id="orbit-progress" cx="100" cy="100" r="88" pathLength="100" stroke-dasharray="0 100"/></svg><div class="orbit-spinner"></div><div class="orbit-satellite satellite-one"></div><div class="orbit-satellite satellite-two"></div><div class="orbit-mesh"></div><svg class="context-lattice" id="context-lattice" viewBox="0 0 260 260" aria-hidden="true"></svg><div class="engine-core">${icon('cpu')}<strong id="orbit-count">0<span style="font-size:.5em;color:#7c768e"> / ${count}</span></strong><small id="orbit-status">EVENTS SCORED</small></div><span class="engine-badge" id="engine-badge">LLM CLASSIFIER</span></div><div class="node-label">03 / CLASSIFY<b id="model-label">${escapeHTML(config.classifierModel)}</b></div></div><div class="flow-group flow-verdicts"><div class="verdict-node" id="tp-node"><strong id="tp-count">—</strong><div><b>TP</b><small>True positive</small></div></div><div class="verdict-node fp" id="fp-node"><strong id="fp-count">—</strong><div><b>FP</b><small>False positive</small></div></div><div class="node-label">04 / EVALUATE<b>Evidence + labels</b></div></div></div>${evidenceScanner()}<div class="pipeline-steps">${['Ingest events','Retrieve context','Classify TP / FP','Evaluate quality'].map((s,i)=>`<div class="flow-step" data-step="${i}"><span>0${i+1}</span>${s}</div>`).join('')}</div><div class="run-progress"><label id="run-progress-text">0 / ${count} events</label><div class="progress-track" role="progressbar" aria-label="Evaluation progress" aria-valuemin="0" aria-valuemax="${count}" aria-valuenow="0"><div class="progress-fill" id="progress-fill"></div></div><span class="clock-time" id="elapsed-time">00:00</span><button data-action="cancel" id="cancel-button" hidden>Stop</button></div></section>`;}
function docStack(docs){return (docs.length?docs.slice(0,5):Array.from({length:5},(_,i)=>({id:`CHUNK ${i+1}`,score:null}))).map((c,i)=>`<div class="mini-doc" style="--i:${i}">${icon('doc')}<span>${escapeHTML(c.id.length>9?c.id.slice(0,9):c.id)}</span><b>${c.score==null?'—':c.score.toFixed(2)}</b></div>`).join('');}
const metricDefinitions={
 relevance:{title:'Context Relevance',group:'RETRIEVAL',description:'How much retrieved evidence is useful for this event?',formula:'Relevant retrieved chunks ÷ retrieved chunks',details:'The OpenAI evaluator checks each context against the event, independently of the predicted verdict. This is a custom binary relevance judgment, averaged per event. Retrieval similarity scores are not relevance scores.',needs:'Enable LLM retrieval + grounding and enter your OpenAI key.'},
 sufficiency:{title:'Context Sufficiency (Recall)',group:'COVERAGE',description:'Does the evidence cover the reference explanation?',formula:'Reference claims supported by context ÷ all reference claims',details:'The custom judge measures coverage of analyst reference facts. Native RAGAS Context Recall is displayed separately when the runner is enabled. These scores measure reference coverage, not general certainty that the evidence is complete.',needs:'Requires reference_explanation from your EMS and an evaluator. TP/FP labels alone are insufficient.'},
 retrieval:{title:'Precision@k / Recall@k',group:'RETRIEVAL',description:'How many known relevant chunks did retrieval find?',formula:'P@k = relevant hits ÷ k · R@k = relevant hits ÷ all relevant IDs',details:'Deterministic retrieval metrics use a complete analyst-curated relevant_context_ids set. Missing retrieval positions count as misses for Precision@k. Recall@k is undefined for an empty reference set. Results average eligible events. Existing EMS decisions use their original context count as k. RAGAS context precision is rank-weighted and is a separate metric.',needs:'Add relevant_context_ids to the adapter. Omit the field if relevance is unknown; do not send a partial relevance list.'},
 grounding:{title:'Groundedness / Faithfulness',group:'GENERATION',description:'Are the answer’s claims supported by evidence?',formula:'Supported rationale claims ÷ all rationale claims',details:'Groundedness is the custom OpenAI claim-support score against retrieved evidence. Faithfulness is computed separately by the native RAGAS library. High grounding does not guarantee a correct TP/FP decision.',needs:'Groundedness requires the OpenAI evaluator. Native faithfulness additionally requires the RAGAS Python runner.'},
 correctness:{title:'Answer Correctness',group:'DECISION',description:'Does the TP/FP answer match the analyst?',formula:'Correct TP/FP answers ÷ analyst-labelled answers',details:'For this binary classification use case, answer correctness is exact analyst-label agreement (accuracy). Native RAGAS Factual Correctness separately evaluates the explanation against reference_explanation, using claim F1.',needs:'Requires analyst_label. Unlabelled events are excluded. Rationale factuality also requires a reference explanation and the RAGAS runner.'},
 f1:{title:'F1 score',group:'CLASSIFICATION',description:'How well are true incidents detected?',formula:'2 × true positives ÷ (2 × true positives + false positives + false negatives)',details:'Classification F1 treats the TP event label as the positive class. Precision and recall come from analyst-labelled successful decisions only. Undefined denominators are shown as a dash. Uncertain decisions remain included and are flagged for review.',needs:'Requires analyst-confirmed TP/FP labels. This calculation does not need a model call.'}
};
function scoreRail(value){return `<div class="score-rail ${Number.isFinite(value)?'has-value':''}" aria-hidden="true">${Array.from({length:24},(_,i)=>`<i class="${Number.isFinite(value)&&i<Math.round(value*24)?'filled':''}"></i>`).join('')}</div>`;}
function metricTile(key,value,sub,secondary='',count=0){const m=metricDefinitions[key];return `<button class="metric-card metric-${key}" data-metric="${key}" aria-label="${m.title}: ${Number.isFinite(value)?pct(value,1):'not available'}. View definition."><div class="metric-heading"><span>${m.group}</span>${icon('arrow')}</div><h3>${m.title}</h3><div class="metric-main"><strong>${Number.isFinite(value)?pct(value,0):'—'}</strong><span>${sub}</span></div>${scoreRail(value)}<div class="metric-bottom">${secondary||`${count} eligible events`}<span>Details ${icon('chevron')}</span></div></button>`;}
function metricsHTML(){const s=summarize(currentRun?.results||[]),judgeLabel=currentRun?.preview?'example checks':'OpenAI judge';return [
 metricTile('relevance',s.contextRelevance,s.contextRelevanceCount?`${s.contextRelevanceCount} events · ${judgeLabel}`:'Awaiting context judgments','Useful chunks / retrieved chunks',s.contextRelevanceCount),
 metricTile('sufficiency',s.contextSufficiency,s.contextSufficiencyCount?`${s.contextSufficiencyCount} reference-scored events`:'Needs evaluator + reference',`RAGAS recall <b>${pct(s.contextRecall)}</b>`,s.contextSufficiencyCount),
 metricTile('retrieval',s.precisionAtK,s.precisionAtKCount?`Precision@${currentRun?.config.mode==='existing'?'k':currentRun?.config.topK||config.topK} · ${s.precisionAtKCount} events`:'Needs relevance labels',`Recall@k <b>${pct(s.recallAtK)}</b>`,s.precisionAtKCount),
 metricTile('grounding',s.evidenceSupport,s.supportCount?`${s.supportCount} events · ${judgeLabel}`:'Awaiting claim-support checks',`RAGAS faithfulness <b>${pct(s.faithfulness)}</b>`,s.supportCount),
 metricTile('correctness',s.accuracy,`${s.labelled} labelled · ${s.unlabelled} unlabelled excluded`,`Rationale factuality <b>${pct(s.answerFactuality)}</b>`,s.labelled),
 metricTile('f1',s.f1,'TP = positive class',`Precision <b>${pct(s.precision)}</b> · Recall <b>${pct(s.recall)}</b>`,s.labelled)
 ].join('');}
function metricsBoard(){return `<section class="metrics-board" aria-label="Evaluation metrics"><div class="metrics-title"><div><span class="section-label">QUALITY BREAKDOWN</span><h2>Evaluation metrics</h2></div><span id="metric-provenance">${currentRun?.preview?'ILLUSTRATIVE RESULTS':currentRun?'CURRENT RUN':'AWAITING EVALUATION'}</span></div><div class="telemetry-grid" id="telemetry-grid">${metricsHTML()}</div></section>`;}
function metricDialog(key){const m=metricDefinitions[key];if(!m)return;const s=summarize(currentRun?.results||[]);openDialog(m.title,m.description,`<div class="metric-formula">${m.formula}</div><p class="detail-text">${m.details}</p><h3 class="guide-heading">Inputs needed</h3><p class="detail-text">${m.needs}</p>${key==='retrieval'?`<h3 class="guide-heading">Native RAGAS context precision</h3><p class="detail-text">${pct(s.contextPrecision)} · ${s.contextPrecisionCount} scored events. Separate from fixed-k precision.</p>`:''}${currentRun?.preview?'<div class="notice" style="margin-top:18px">These are illustrative walkthrough results, not model evaluation scores.</div>':''}`,`<button class="button secondary small" data-action="close">Close</button>`);}
function evidenceScanner(){return `<div class="evidence-scanner"><div class="scanner-heading"><span class="scanner-pulse"></span><span id="scanner-mode">EXAMPLE EVIDENCE TOUR</span><button class="scanner-motion" data-action="motion" aria-label="Pause or resume continuous motion">${icon('motion')}<span id="scanner-motion-label">${reducedMotion?'Resume motion':'Pause motion'}</span></button></div><div class="scanner-content"><div class="scanner-index"><b id="scanner-rank">01</b><small>CONTEXT</small></div><div class="scanner-copy"><div><strong id="scanner-title">Evidence inspection</strong><span id="scanner-id"></span></div><p id="scanner-text">Waiting for evidence from the event feed.</p></div><div class="scanner-confidence"><strong id="scanner-score">—</strong><small>RETRIEVAL SCORE</small></div></div><div class="scanner-timeline" id="scanner-timeline"></div></div>`;}
function updateScanner(advance=false){
 if(page!=='pipeline'||!$('.evidence-scanner'))return;
 const docs=selectedContext(),flow=$('#flow-visual');
 if(advance)scanTick++;
 const index=docs.length?Math.floor(scanTick/4)%docs.length:0,c=docs[index];
 const lattice=$('#context-lattice'),latticeKey=docs.map(d=>d.id).join('|');
 if(lattice&&lattice.dataset.key!==latticeKey){lattice.dataset.key=latticeKey;lattice.innerHTML=docs.map((d,i)=>{const angle=i/Math.max(docs.length,1)*Math.PI*2-.8,x=130+Math.cos(angle)*116,y=130+Math.sin(angle)*102;return `<g class="context-link" data-link="${i}"><path d="M${x} ${y} Q${130+Math.cos(angle+.7)*84} ${130+Math.sin(angle+.7)*84} 130 130"/><circle cx="${x}" cy="${y}" r="3"/><circle class="context-halo" cx="${x}" cy="${y}" r="7"/></g>`;}).join('');}
 $$('.context-link').forEach((el,i)=>el.classList.toggle('selected',i===index));
 const ambient=!running&&(config.dataSource==='example'||!!currentRun),label=running?(currentRun?.preview?'WALKTHROUGH · EXAMPLE EVIDENCE':'RUNNING · RETRIEVED EVIDENCE'):currentRun?'REPLAY · NO NEW REQUESTS':config.dataSource==='example'?'EXAMPLE EVIDENCE TOUR · NO API CALLS':'STANDBY · WAITING FOR EMS';
 flow.dataset.ambient=ambient?'true':'false';
 $('#scanner-mode').textContent=label;
 $('#scanner-motion-label').textContent=reducedMotion?'Resume motion':'Pause motion';
 $('#scanner-rank').textContent=c?String(index+1).padStart(2,'0'):'—';
 $('#scanner-title').textContent=c?.title||'Evidence inspection';$('#scanner-id').textContent=c?.id||'';
 $('#scanner-text').textContent=c?.text||'Connect your EMS and run an evaluation to inspect retrieved context.';
 $('#scanner-score').textContent=c?.score==null?'—':c.score.toFixed(2);
 const timeline=$('#scanner-timeline'),timelineKey=docs.map(d=>d.id).join('|')+':'+index;
 if(timeline.dataset.key!==timelineKey){timeline.dataset.key=timelineKey;timeline.innerHTML=docs.map((d,i)=>`<button aria-label="Inspect context ${i+1}: ${escapeHTML(d.title||d.id)}" data-context-index="${i}" class="${i===index?'active':''}"><span>${String(i+1).padStart(2,'0')}</span><i></i></button>`).join('');}
 $$('.mini-doc').forEach((d,i)=>d.classList.toggle('scanning',i===index));
 if(c?.id!==scanContextID){scanContextID=c?.id||'';$('.scanner-copy').animate?.([{opacity:.25,transform:'translateY(4px)'},{opacity:1,transform:'none'}],{duration:reducedMotion?0:450});}
 if(!running){
   const step=Math.floor(scanTick/4)%4;
   flow.dataset.tourStep=step;
   $$('.flow-step').forEach((el,i)=>el.classList.toggle('tour-active',ambient&&step===i));
   if(!currentRun){$('#pipeline-badge').innerHTML=`<i></i>${config.dataSource==='example'?'EXAMPLE FLOW':'STANDBY'}`;$('#pipeline-badge').className='status-pill live';$('#orbit-status').textContent=config.dataSource==='example'?'EXAMPLE CONTEXTS':'AWAITING EVENTS';$('#orbit-count').innerHTML=String(docs.length).padStart(2,'0');$('#engine-badge').textContent='EVIDENCE → DECISION';}
 }
}
function eventList(){return selectedEvents().map(e=>{const r=getResult(e.id),active=running&&flowState.eventID===e.id;return `<button class="event-row ${selectedID===e.id?'selected':''}" data-event="${escapeHTML(e.id)}"><span class="source-logo ${e.source==='Troj'?'troj':''}">${e.source[0]}</span><span class="event-info"><strong>${escapeHTML(e.title)}</strong><small>${escapeHTML(e.id)} · ${e.analyst_label?'Analyst labelled':'Awaiting analyst label'}</small></span><span class="event-status ${active?'running':statusClass(r)}">${active?'Running':stateText(r)}</span></button>`;}).join('')||'<div class="log-empty"><p>No events in the selected sources.</p></div>';}
function logHTML(){return logs.length?logs.slice(-60).reverse().map(l=>`<div class="log-entry ${l.type||''}"><time>${l.time}</time><span class="log-point"></span><div><strong>${escapeHTML(l.message)}</strong><small>${escapeHTML(l.detail)}</small></div></div>`).join(''):`<div class="log-empty">${icon('activity')}<b>Your execution trace appears here.</b><p>See retrieval, classification, and scoring<br>as each event is processed.</p></div>`;}
function pipelinePage(){return `<div class="studio-layout page-enter">${configPanel()}<div class="workspace-main"><div class="monitor-grid">${pipelineDiagram()}${metricsBoard()}</div><div class="split-row"><section class="panel"><div class="panel-heading"><div><h2>Event queue</h2><p>Inspect the evidence behind each event</p></div><button class="text-link" data-page="events">View all ${icon('arrow')}</button></div><div class="event-list" id="event-list">${eventList()}</div></section><section class="panel"><div class="panel-heading"><div><h2>Execution trace</h2><p id="log-subtitle">Timestamped run activity</p></div><span class="mini-count" id="log-count">${logs.length} LOGS</span></div><div class="trace-log" id="trace-log">${logHTML()}</div></section></div></div></div>`;}
function eventsPage(results=false){const resultIDs=new Set(currentRun?.results.map(r=>r.event.id)||[]);let filtered=(results?events.filter(e=>resultIDs.has(e.id)):events).filter(e=>(eventFilter==='all'||e.source===eventFilter)&&`${e.title} ${e.id} ${e.source}`.toLowerCase().includes(eventSearch.toLowerCase()));return `<section class="panel table-panel page-enter"><div class="table-toolbar"><div><h2>${results?'Event results':'Event queue'}</h2><p class="status-line">${results?(currentRun?.preview?'Illustrative walkthrough · not model results':`${escapeHTML(currentRun?.config.mode==='existing'?'EMS decisions':'OpenAI classifications')} · ${escapeHTML(currentRun?.status||'')}`):(config.dataSource==='ems'?'Events from your EMS adapter':'Six fictional integration examples · no live data')}</p></div><div class="tools"><input class="input search-input" id="event-search" type="search" aria-label="Search events" placeholder="Find an event…" value="${escapeHTML(eventSearch)}"><select id="event-filter" aria-label="Filter event source"><option value="all">All sources</option>${['Zenity','Troj'].map(s=>`<option ${eventFilter===s?'selected':''}>${s}</option>`).join('')}</select>${results?`<button class="button small" data-action="export" ${currentRun?'':'disabled'}>${icon('download')}Export</button>`:`<button class="button small" data-action="sync" ${running?'disabled':''}>${icon('refresh')}Sync</button>`}</div></div><div class="table-scroll"><table><thead><tr><th>EVENT / SOURCE</th><th>SEVERITY</th><th>LLM DECISION</th><th>CONFIDENCE</th><th>ANALYST LABEL</th><th>EVIDENCE</th><th></th></tr></thead><tbody>${filtered.length?filtered.map(e=>{const r=getResult(e.id),active=running&&flowState.eventID===e.id;return `<tr><td><button class="event-title" data-event="${escapeHTML(e.id)}">${escapeHTML(e.title)}</button><small>${escapeHTML(e.id)} · ${e.source}</small></td><td><span class="severity ${e.severity==='high'||e.severity==='critical'?'high':''}">${e.severity.toUpperCase()}</span></td><td><span class="event-status ${active?'running':statusClass(r)}">${active?'Running':stateText(r)}</span>${r?.decision&&stateText(r)==='Review'?`<small>Tentative ${r.decision.verdict}</small>`:''}</td><td class="mono">${pct(r?.decision?.confidence)}</td><td>${e.analyst_label||'<span class="dim">Unlabelled</span>'}</td><td class="mono">${num(r?.judge?.evidence_support)}</td><td><button class="quiet icon-only" data-event="${escapeHTML(e.id)}" aria-label="Inspect ${escapeHTML(e.id)}">${icon('chevron')}</button></td></tr>`;}).join(''):'<tr><td colspan="7"><div class="wide-empty"><p>No events match this view.</p></div></td></tr>'}</tbody></table></div><div class="table-foot"><span>${filtered.length} events · select an event for its full trace</span><span>Confidence is self-assessed, not calibrated</span></div></section>`;}
function resultsPage(){if(!currentRun)return `<section class="panel wide-empty page-enter">${icon('chart')}<h2>No evaluation results yet</h2><p>Run events through the pipeline to inspect retrieval quality, evidence support, and classification performance.</p><button class="button primary" data-page="pipeline">Open pipeline ${icon('arrow')}</button></section>`;const s=summarize(currentRun.results);return `<div class="page-enter">${metricsBoard()}<div class="result-grid"><section class="panel"><div class="panel-heading"><div><h2>Classification confusion matrix</h2><p>${s.labelled} labelled events · ${s.unlabelled} unlabelled excluded${currentRun.preview?' · illustrative':''}</p></div><span class="status-pill">TP = POSITIVE CLASS</span></div><div class="matrix-label">Predicted: TP ← → FP</div><div class="matrix-wrap"><div class="matrix-axis">Analyst: TP ← → FP</div><div class="matrix">${[[s.tp,'Correct TP','Actual TP → predicted TP',false],[s.fn,'Missed incident','Actual TP → predicted FP',true],[s.fp,'False alarm','Actual FP → predicted TP',true],[s.tn,'Correct FP','Actual FP → predicted FP',false]].map(([v,l,d,b])=>`<div class="matrix-cell ${b?'bad':''}"><strong>${v}</strong><span>${l}</span><small>${d}</small></div>`).join('')}</div></div></section><section class="panel"><div class="panel-heading"><div><h2>Classification performance</h2><p>Measured against available analyst labels</p></div></div><div class="bars">${[['Precision',s.precision],['Recall',s.recall],['F1 score',s.f1],['Accuracy',s.accuracy]].map(([n,v])=>`<div><div class="bar-heading"><span>${n}</span><strong class="mono">${pct(v,1)}</strong></div><div class="bar-track"><i style="--w:${v==null?0:v*100}%"></i></div></div>`).join('')}</div><p class="metric-note">Unlabelled events and failed classifications are excluded. A dash means there is no valid denominator. Low-confidence predictions are included and flagged for analyst review.</p></section></div>${eventsPage(true)}</div>`;}
function historyPage(){return `<section class="panel page-enter">${history.length?`<div class="panel-heading"><div><h2>Run history</h2><p>This session only · export a run to keep its full trace</p></div></div>${history.map((r,i)=>{const s=summarize(r.results);return `<div class="history-item">${icon('clock')}<div><h3>${escapeHTML(r.id)} ${r.preview?'<span class="history-badge">EXAMPLE</span>':''}</h3><p>${new Date(r.started_at).toLocaleString()} · ${r.results.length} events · ${r.config.dataSource==='ems'?'Connected EMS':'Example events'} · ${escapeHTML(r.status)}</p></div><span class="history-badge">F1 ${num(s.f1)}</span><button class="button small" data-history="${i}">Inspect run ${icon('arrow')}</button></div>`;}).join('')}`:`<div class="wide-empty">${icon('clock')}<h2>No runs in this session</h2><p>Completed and stopped runs appear here with their settings and event results. Nothing sensitive is saved to browser storage.</p><button class="button secondary" data-page="pipeline">Open pipeline ${icon('arrow')}</button></div>`}</section>`;}
function render(){const content=page==='pipeline'?pipelinePage():page==='events'?eventsPage():page==='results'?resultsPage():historyPage();$('#content').innerHTML=content;$$('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);if(b.getAttribute('role')==='tab')b.setAttribute('aria-selected',String(b.dataset.page===page));});$('#page-label').textContent=labels[page];$('#event-count').textContent=events.length.toString().padStart(2,'0');updateHeader();if(page==='pipeline')updateLive();}
function navigate(next){page=labels[next]?next:'pipeline';render();window.scrollTo({top:0,behavior:'instant'});}
function updateHeader(){const key=!!secrets.apiKey;$('#connection-label').textContent=key?(connectionVerified?'OpenAI connected':'OpenAI key set'):'Connect services';$('#connection-dot').classList.toggle('connected',key&&connectionVerified);$('#engine-label').textContent=config.ragas?(config.judge?'OpenAI + RAGAS':'Native RAGAS'):config.judge?'OpenAI evaluator':'Analyst-label comparison';$('#workspace-state').textContent=running?(currentRun?.preview?'Walkthrough playing':'Evaluation in progress'):currentRun?currentRun.status:key?'Ready to evaluate':'Ready to configure';$('#run-button').disabled=running;$('#run-button').innerHTML=icon('play')+(running?'Evaluating…':'Evaluate events');$$('[data-action="walkthrough"]').forEach(b=>b.disabled=running);$('#footer-engine').textContent=config.dataSource==='ems'?'EMS adapter selected':key?'Example events · OpenAI key set':'No live services connected';const preview=currentRun?.preview;$('#mode-banner').innerHTML=icon(preview?'eye':config.dataSource==='ems'?'plug':'beaker')+`<span>${preview?'<strong>Illustrative walkthrough</strong> · No OpenAI or RAGAS calls. These are example decisions.':config.dataSource==='ems'?'<strong>Connected EMS mode</strong> · Events and retrieval come from your adapter.':'<strong>Example events</strong> · Connect your EMS for live events. The evidence tour makes no model calls.'}</span><button data-action="connections">Connection settings ${icon('arrow')}</button>`;}
function updateLive(){if(page!=='pipeline')return;const r=currentRun,s=summarize(r?.results||[]),total=r?r.total:selectedEvents().length,completed=r?r.results.length:0,stage=flowState.stage;$('#flow-visual').dataset.stage=running?stage:'idle';$('#flow-visual').dataset.source=currentEvent()?.source||'';$('#flow-visual').dataset.verdict=flowState.verdict||'';$('#orbit-count').innerHTML=`${completed}<span style="font-size:.5em;color:#7c768e"> / ${total}</span>`;$('#orbit-status').textContent=running?(r?.preview?'EXAMPLE TRACE':stage==='classify'?'CLASSIFYING':stage==='evaluate'?'EVALUATING':'RETRIEVING'):'EVENTS SCORED';$('#orbit-progress').setAttribute('stroke-dasharray',`${total?completed/total*100:0} 100`);$('#tp-count').textContent=r?s.predictedTP:'—';$('#fp-count').textContent=r?s.predictedFP:'—';$('#run-progress-text').textContent=`${completed} / ${total} events`;$('#progress-fill').style.width=`${total?completed/total*100:0}%`;const bar=$('.progress-track');bar.setAttribute('aria-valuemax',total);bar.setAttribute('aria-valuenow',completed);$('#cancel-button').hidden=!running;const badge=$('#pipeline-badge');badge.className=`status-pill ${running?'live':r?.status==='failed'?'error':r?'done':''}`;badge.innerHTML=`<i></i>${running?(r?.preview?'WALKTHROUGH':'RUNNING'):r?(r.status==='cancelled'?'STOPPED':r.status==='failed'?'FAILED':r.status==='completed_with_errors'?'FINISHED · ERRORS':'COMPLETE'):'AWAITING RUN'}`;$('#model-label').textContent=r?.preview?'Walkthrough trace':config.mode==='existing'?(getResult(currentEvent()?.id)?.model||'Original EMS model'):config.classifierModel;$('#engine-badge').textContent=r?.preview?'EXAMPLE DECISIONS':config.mode==='existing'?'EMS DECISIONS':'LLM CLASSIFIER';$('#pipeline-subtitle').textContent=running&&currentEvent()?`${currentEvent().id} · ${stage==='retrieve'?'Retrieving evidence':stage==='classify'?'Requesting TP / FP decision':stage==='evaluate'?'Checking evidence support':'Processing event'}`:'Event → evidence → decision → evaluation';$('#retrieval-stack').innerHTML=docStack(selectedContext());$('#retrieval-label').textContent=config.mode==='existing'?`${selectedContext().length} original contexts`:`${selectedContext().length} / ${config.topK} contexts`;$('#telemetry-grid').innerHTML=metricsHTML();$('#event-list').innerHTML=eventList();$('#trace-log').innerHTML=logHTML();$('#log-count').textContent=`${logs.length} LOGS`;$('#log-subtitle').textContent=r?.preview?'Illustrative trace · no model calls':'Timestamped run activity';const idx={ingest:0,retrieve:1,classify:2,evaluate:3,complete:4}[stage]??-1;$$('[data-step]').forEach(el=>{el.classList.toggle('active',running&&Number(el.dataset.step)===idx);el.classList.toggle('complete',r&&(Number(el.dataset.step)<idx||!running&&r.status==='completed'));});updateElapsed();updateScanner();}
function updateElapsed(){if(!$('#elapsed-time'))return;const t=currentRun?Math.floor(((running?Date.now():currentRun.ended_at||Date.now())-new Date(currentRun.started_at).getTime())/1000):0;$('#elapsed-time').textContent=`${Math.floor(t/60).toString().padStart(2,'0')}:${(t%60).toString().padStart(2,'0')}`;}
function addLog(message,detail='',type=''){const seconds=currentRun?Math.floor((Date.now()-new Date(currentRun.started_at).getTime())/1000):0;logs.push({time:`${Math.floor(seconds/60).toString().padStart(2,'0')}:${(seconds%60).toString().padStart(2,'0')}`,message,detail,type,timestamp:new Date().toISOString()});if(currentRun)currentRun.logs=logs;if(page==='pipeline')updateLive();}
function openDialog(title,subtitle,body,footer=''){dialogFocus=document.activeElement;$('#dialog-content').innerHTML=`<div class="dialog-header"><div><h2 id="dialog-title">${title}</h2><p>${subtitle}</p></div><button class="close" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;$('#dialog').setAttribute('aria-labelledby','dialog-title');if(!$('#dialog').open)$('#dialog').showModal();}
function closeDialog(){$('#dialog').close();$('#dialog-content').innerHTML='';if(dialogFocus?.isConnected)dialogFocus.focus({preventScroll:true});}
function connectionDialog(){openDialog('Service connections','Connect your EMS, OpenAI, and the optional RAGAS runner.',`<form id="connection-form"><section class="settings-section"><div class="settings-title">${icon('cpu')}<h3>OpenAI</h3><span>${secrets.apiKey?'KEY IN SESSION':'REQUIRED FOR LIVE CLASSIFICATION'}</span></div><div class="field"><label for="api-key">API key</label><input id="api-key" class="input" type="password" autocomplete="off" spellcheck="false" placeholder="${secrets.apiKey?'Key is set · leave blank to keep it':'Enter your OpenAI API key'}"><small>The key is sent through this private site to api.openai.com. It is never saved to browser storage or written to application logs.</small></div><div class="two-fields"><div class="field"><label for="classifier-model">Classifier model</label><input id="classifier-model" class="input" value="${escapeHTML(config.classifierModel)}" placeholder="gpt-4.1-mini"></div><div class="field"><label for="judge-model">Evaluator model</label><input id="judge-model" class="input" value="${escapeHTML(config.judgeModel)}" placeholder="gpt-4.1-mini"></div></div><div class="settings-actions"><button type="button" class="button small" data-action="test-openai">Test OpenAI connection ${icon('arrow')}</button><button type="button" class="text-link" data-action="clear-key">Clear session key</button></div><p id="openai-status" class="settings-status" role="status"></p></section><section class="settings-section"><div class="settings-title">${icon('plug')}<h3>Event Management System</h3><span>ZENITY + TROJ ADAPTER</span></div><div class="field"><label for="ems-url">Adapter base URL</label><input id="ems-url" class="input" type="url" value="${escapeHTML(config.emsURL)}" placeholder="https://your-ems.example.com"><small>GET /v1/events and POST /v1/retrieve. The browser calls your adapter directly; allow this site's origin in CORS.</small></div><div class="field"><label for="ems-token">Adapter bearer token · optional</label><input id="ems-token" class="input" type="password" autocomplete="off" placeholder="${secrets.emsToken?'Token is set · leave blank to keep it':'Session only'}"></div><button type="button" class="text-link" data-action="guide">View the adapter contract ${icon('arrow')}</button></section><section class="settings-section"><div class="settings-title">${icon('beaker')}<h3>RAGAS Python runner</h3><span>OPTIONAL · NATIVE METRICS</span></div><div class="field"><label for="ragas-url">Runner base URL</label><input id="ragas-url" class="input" type="url" value="${escapeHTML(config.ragasURL)}" placeholder="https://your-ragas-runner.example.com"><small>The included Python service runs ragas 0.4.3. When enabled, your event evidence and OpenAI key are sent to this runner for scoring.</small></div><div class="field"><label for="ragas-token">Runner bearer token</label><input id="ragas-token" class="input" type="password" autocomplete="off" placeholder="${secrets.ragasToken?'Token is set · leave blank to keep it':'Required by the runner'}"></div><a class="text-link" href="/axiom-ragas-runner.zip" download>${icon('download')}Download the RAGAS runner</a></section><section class="settings-section"><div class="settings-title">${icon('shield')}<h3>Classification policy</h3></div><div class="field"><label for="policy">Instructions applied to each event</label><textarea id="policy" rows="6" maxlength="6000">${escapeHTML(config.policy)}</textarea><small>Event content and retrieved documents are treated as evidence. Analyst labels and reference explanations are excluded from classifier input.</small></div></section><div class="secret-note">${icon('lock')}Keys and tokens last only until this page is refreshed. Connection URLs and model preferences are saved on this device. Running an evaluation sends selected event data to the services you configure and may incur provider charges.</div><p class="settings-status error" id="connection-error" role="alert"></p></form>`,`<small>Use an OpenAI model supporting structured outputs.</small><button class="button primary" data-action="save-connections">Save connections ${icon('check')}</button>`);}
function readConnectionForm(){const apiKey=$('#api-key')?.value.trim(),emsToken=$('#ems-token')?.value.trim(),ragasToken=$('#ragas-token')?.value.trim();const emsURL=$('#ems-url').value.trim(),ragasURL=$('#ragas-url').value.trim(),classifierModel=$('#classifier-model').value.trim(),judgeModel=$('#judge-model').value.trim();if(emsURL)validateServiceURL(emsURL);if(ragasURL)validateServiceURL(ragasURL);if(!/^[a-zA-Z0-9._:-]{1,100}$/.test(classifierModel)||!/^[a-zA-Z0-9._:-]{1,100}$/.test(judgeModel))throw Error('Enter valid model IDs.');return{apiKey:apiKey||secrets.apiKey,emsToken:emsToken||secrets.emsToken,ragasToken:ragasToken||secrets.ragasToken,emsURL,ragasURL,classifierModel,judgeModel,policy:$('#policy').value.trim()||defaultPolicy};}
async function testOpenAI(){const status=$('#openai-status'),button=$('[data-action="test-openai"]');try{const f=readConnectionForm();if(!f.apiKey)throw Error('Enter your OpenAI API key first.');button.disabled=true;status.className='settings-status';status.textContent='Checking model access…';for(const model of new Set([f.classifierModel,f.judgeModel])){await jsonFetch('/api/check',{method:'POST',headers:{'Content-Type':'application/json','X-OpenAI-Key':f.apiKey},body:JSON.stringify({model})},15000);}secrets.apiKey=f.apiKey;connectionVerified=true;status.textContent='Connected. Both selected models are accessible.';updateHeader();}catch(e){status.className='settings-status error';status.textContent=e.message;connectionVerified=false;}finally{button.disabled=false;}}
function saveConnections(){try{const f=readConnectionForm();if(f.apiKey!==secrets.apiKey)connectionVerified=false;Object.assign(secrets,{apiKey:f.apiKey,emsToken:f.emsToken,ragasToken:f.ragasToken});Object.assign(config,{emsURL:f.emsURL,ragasURL:f.ragasURL,classifierModel:f.classifierModel,judgeModel:f.judgeModel,policy:f.policy});saveSettings();closeDialog();render();toast('Connections saved. Keys remain in this page session only.');}catch(e){$('#connection-error').textContent=e.message;}}
function guide(){openDialog('EMS adapter contract','A small interface between your application and the evaluation workspace.',`<div class="notice">The adapter is a contract for your EMS integration. The example events in this app are fictional; no Zenity or Troj systems are connected yet.</div><h3 class="guide-heading">1. Fetch events</h3><pre class="codeblock">GET /v1/events?source=Zenity,Troj&amp;limit=6
Authorization: Bearer &lt;your adapter token&gt;

{
  "events": [{
    "id": "ZNT-1042", "source": "Zenity",
    "title": "External sharing detected",
    "description": "Event facts and audit details…",
    "severity": "high", "attributes": {},
    "occurred_at": "2026-10-19T07:42:00Z",
    "analyst_label": "TP",
    "reference_explanation": "Analyst rationale…",
    "relevant_context_ids": ["POL-014", "AUD-042"]
  }],
  "next_cursor": null
}</pre><p class="field-help">Sources are <strong>Zenity</strong> or <strong>Troj</strong>. Analyst labels are <strong>TP</strong>, <strong>FP</strong>, or null. Return only the requested batch. next_cursor is reserved for your adapter; this workspace evaluates one batch per run.</p><p class="field-help"><strong>Metric references:</strong> supply reference_explanation for context sufficiency and rationale factuality. Supply relevant_context_ids only when you have the complete relevant chunk set, including relevant chunks not retrieved; omit it when unknown. All reference fields are hidden from the classifier.</p><h3 class="guide-heading">2. Retrieve evidence</h3><pre class="codeblock">POST /v1/retrieve
{
  "event_id": "ZNT-1042",
  "query": "Event title + description",
  "top_k": 5
}

{
  "contexts": [{
    "id": "POL-014", "title": "Sharing policy",
    "text": "Customer records must not be…",
    "score": 0.94
  }]
}</pre><p class="field-help">Return evidence in retrieval rank order. The score is your retriever's native score, not an evaluation metric. The adapter owns vector search and the connection to your data sources.</p><h3 class="guide-heading">3. Evaluate existing EMS decisions</h3><pre class="codeblock">// Optional fields on each event:
"contexts": [{ "id": "POL-014", "text": "…" }],
"decision": {
  "verdict": "TP", "confidence": 0.91,
  "rationale": "Evidence-backed explanation…",
  "cited_context_ids": ["POL-014"],
  "insufficient_evidence": false,
  "model": "your-production-model"
}</pre><p class="field-help">Use <strong>Evaluate EMS decisions</strong> to score the original decision against its original contexts. No new classification or retrieval is performed in that mode.</p><h3 class="guide-heading">CORS and transport</h3><pre class="codeblock">Access-Control-Allow-Origin: ${escapeHTML(location.origin)}
Access-Control-Allow-Methods: GET, POST, OPTIONS
Access-Control-Allow-Headers: Content-Type, Authorization</pre><p class="field-help">Use HTTPS for remote adapters. A localhost runner may be blocked by browser private-network rules when called from a hosted page; deploy it behind HTTPS for the published workspace. Service tokens are kept in memory. A run does not write labels back or take remediation actions in your EMS.</p><h3 class="guide-heading">Native RAGAS</h3><p class="field-help">The included runner executes Faithfulness, ContextPrecision, and ContextRecall from RAGAS. Context precision and recall need a reference explanation; events without one are explicitly skipped for those metrics. Custom OpenAI evidence-support scores remain separate.</p><p class="field-help"><a href="https://docs.ragas.io/en/stable/concepts/metrics/available_metrics/faithfulness/" target="_blank" rel="noopener">RAGAS metric documentation ↗</a></p>`,`<a class="button secondary small" href="/adapter-contract.json" download>${icon('download')}Adapter schema</a><a class="button primary small" href="/axiom-ragas-runner.zip" download>${icon('download')}Python runner</a>`);}
function inspectEvent(id){selectedID=id;const e=events.find(e=>e.id===id);if(!e)return;const r=getResult(id),d=r?.decision,contexts=r?.contexts||e.contexts||[];if(!running){flowState.eventID=id;flowState.verdict=d?.verdict||'';flowState.contexts=config.mode==='existing'?contexts:contexts.slice(0,config.topK);updateLive();}openDialog(escapeHTML(e.id)+' · '+e.source,escapeHTML(e.title),`${currentRun?.preview?'<div class="notice" style="margin-bottom:18px">Illustrative walkthrough result. No model generated this decision.</div>':''}<div class="detail-kpis"><div class="detail-kpi"><span>LLM decision</span><strong>${d?.verdict||'Not run'}</strong></div><div class="detail-kpi"><span>Self-assessed confidence</span><strong>${pct(d?.confidence)}</strong></div><div class="detail-kpi"><span>Analyst label</span><strong>${e.analyst_label||'Unlabelled'}</strong></div></div>${d&&(d.insufficient_evidence||d.confidence<config.confidenceThreshold)?`<div class="notice">${icon('alert')} This decision needs analyst review because evidence is incomplete or confidence is below ${pct(config.confidenceThreshold)}.</div>`:''}${r?.error?`<div class="notice">${escapeHTML(r.error)}</div>`:''}<h3 class="guide-heading">Event facts</h3><p class="detail-text">${escapeHTML(e.description)}</p><h3 class="guide-heading">Decision rationale</h3><p class="detail-text">${d?escapeHTML(d.rationale):'Run the evaluation to generate a decision, or connect an existing EMS decision.'}</p>${d?`<p class="field-help">${escapeHTML(r?.model||d.model||config.classifierModel)} · ${r?.latency_ms?(r.latency_ms/1000).toFixed(2)+' s · ':''}${r?.tokens||0} reported model tokens</p>`:''}${r?.timings?`<h3 class="guide-heading">Execution timing${currentRun?.preview?' · walkthrough playback':''}</h3><div class="timing-bars">${Object.entries(r.timings).map(([stage,ms])=>`<div class="timing-row"><span>${escapeHTML(stage)}</span><i style="--w:${Math.max(1,ms/Math.max(...Object.values(r.timings),1)*100)}%"></i><b>${(ms/1000).toFixed(2)} s</b></div>`).join('')}</div>`:''}<h3 class="guide-heading">Retrieved evidence · ${contexts.length} chunks</h3>${contexts.length?contexts.map((c,i)=>`<article class="evidence-card ${d?.cited_context_ids.includes(c.id)?'cited':''}"><header><strong>${i+1}. ${escapeHTML(c.title||c.id)}</strong><span>${escapeHTML(c.id)}${c.score==null?'':` · ${c.score.toFixed(3)}`}</span></header><p>${escapeHTML(c.text)}</p>${d?.cited_context_ids.includes(c.id)?'<small>Cited by classifier</small>':''}</article>`).join(''):'<p class="field-help">Context will appear after retrieval. The EMS adapter supplies the top-K results.</p>'}<h3 class="guide-heading">Groundedness · claim support</h3>${r?.judge?`<p class="detail-text"><strong>${num(r.judge.evidence_support)}</strong> · ${escapeHTML(r.judge.reason)}</p>${r.judge.claims.map(c=>`<div class="claim ${c.supported?'':'unsupported'}"><span>${c.supported?'Supported':'Unsupported'}</span><div>${escapeHTML(c.text)}<p class="field-help">${escapeHTML(c.reason)}</p></div></div>`).join('')}`:`<p class="field-help">${r?.evaluationError?escapeHTML(r.evaluationError):'No LLM judge result for this event.'}</p>`}${eventMetricDetails(r,e)}<h3 class="guide-heading">Native RAGAS scores</h3>${r?.ragas?Object.entries(r.ragas).map(([key,v])=>`<div class="bar-heading"><span>${escapeHTML(key.replaceAll('_',' '))}</span><strong>${v.status==='skipped'?'Skipped':num(v.value)}</strong></div><p class="field-help">${escapeHTML(v.reason||'')}</p>`).join(''):'<p class="field-help">Not run. Enable native RAGAS and connect the included Python runner.</p>'}${e.reference_explanation?`<h3 class="guide-heading">Analyst reference explanation</h3><p class="detail-text">${escapeHTML(e.reference_explanation)}</p><p class="field-help">Used only for evaluation. Hidden from the classifier.</p>`:''}`,`<small>Retrieval scores and model confidence are distinct.</small><button class="button secondary small" data-action="close">Close</button>`);}
async function jsonFetch(url,options={},timeout=90000){const signal=options.signal?AbortSignal.any([options.signal,AbortSignal.timeout(timeout)]):AbortSignal.timeout(timeout);let response;try{response=await fetch(url,{...options,signal});}catch(e){if(options.signal?.aborted)throw new DOMException('Stopped by user.','AbortError');if(e.name==='TimeoutError')throw Error('The service timed out. Retry or check its health.');throw Error('Could not reach the service. Check its URL, HTTPS availability, and CORS settings.');}let data;try{data=await response.json();}catch{throw Error('The service returned a non-JSON response. Check the adapter URL and API paths.');}if(!response.ok)throw Error(typeof data.error==='string'?data.error:typeof data.detail==='string'?data.detail:`Service request failed (${response.status}).`);return data;}
function serviceHeaders(token){return{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})};}
async function loadEvents(signal){if(config.dataSource==='example'){events=exampleEvents.map(normalizeEvent);return;}if(!config.emsURL)throw Error('Add your EMS adapter URL in Connections.');const base=validateServiceURL(config.emsURL),url=new URL(base+'/v1/events');url.searchParams.set('source',config.sources.join(','));url.searchParams.set('limit',config.limit);const data=await jsonFetch(url.href,{headers:serviceHeaders(secrets.emsToken),signal},30000);if(!Array.isArray(data.events)||data.events.length>50)throw Error('The adapter must return an events array of at most 50 items.');const normalized=data.events.map(normalizeEvent);if(new Set(normalized.map(e=>e.id)).size!==normalized.length)throw Error('The adapter returned duplicate event IDs.');events=normalized;}
async function retrieve(e,signal){if(config.mode==='existing'){if(!e.contexts?.length)throw Error('This EMS decision has no original contexts. Provide the original trace to evaluate it.');return e.contexts;}if(config.dataSource==='example')return(e.contexts||[]).slice(0,config.topK);const data=await jsonFetch(validateServiceURL(config.emsURL)+'/v1/retrieve',{method:'POST',headers:serviceHeaders(secrets.emsToken),signal,body:JSON.stringify({event_id:e.id,query:`${e.title}\n${e.description}`,top_k:config.topK})},30000);return normalizeContexts(data.contexts).slice(0,config.topK);}
async function scoreRagas(event,contexts,decision,signal){const data=await jsonFetch(validateServiceURL(config.ragasURL)+'/v1/evaluate',{method:'POST',headers:{...serviceHeaders(secrets.ragasToken),'X-OpenAI-Key':secrets.apiKey},signal,body:JSON.stringify({event,contexts,decision,model:config.judgeModel})},180000);if(data.engine!=='ragas'||!data.metrics||typeof data.metrics!=='object')throw Error('Runner returned an invalid RAGAS result.');for(const [name,m] of Object.entries(data.metrics)){if(!m||!['ok','skipped'].includes(m.status)||m.status==='ok'&&(!Number.isFinite(m.value)||m.value<0||m.value>1))throw Error(`Invalid RAGAS score for ${name}.`);}return data.metrics;}
function delay(ms,signal){return new Promise((resolve,reject)=>{const abort=()=>{clearTimeout(timer);reject(new DOMException('Stopped','AbortError'));};const timer=setTimeout(()=>{signal.removeEventListener('abort',abort);resolve();},ms);signal.addEventListener('abort',abort,{once:true});if(signal.aborted)abort();});}
async function startRun(preview=false){if(running)return;if(!config.sources.length){toast('Select at least one event source.');return;}if(!preview&&(!secrets.apiKey&&(config.mode==='rerun'||config.judge||config.ragas))){connectionDialog();$('#connection-error').textContent='Enter your OpenAI API key to run live classification or evaluation.';return;}if(!preview&&config.ragas&&(!config.ragasURL||!secrets.ragasToken)){connectionDialog();$('#connection-error').textContent='Native RAGAS requires the runner URL and its bearer token.';return;}if(!preview&&config.dataSource==='ems'&&!config.emsURL){connectionDialog();$('#connection-error').textContent='Add the EMS adapter URL first.';return;}if(!preview&&config.dataSource==='example'&&config.mode==='existing'){toast('Example events do not contain EMS decisions. Choose Re-run OpenAI classifier or connect EMS.');return;}
  if(preview){config.dataSource='example';events=exampleEvents.map(normalizeEvent);}
  controller=new AbortController();const signal=controller.signal;running=true;logs=[];flowState={stage:'ingest',index:0,completed:0,total:0,contexts:[],eventID:null};currentRun={id:`EV-${new Date().toISOString().replace(/[-:T.Z]/g,'').slice(0,14)}`,started_at:new Date().toISOString(),ended_at:null,status:'running',preview,config:{...config,sources:[...config.sources]},results:[],logs,total:0};page='pipeline';render();elapsedTimer=setInterval(updateElapsed,1000);announce(preview?'Example walkthrough started. No model calls.':'Evaluation started.');
  try{addLog(preview?'Example walkthrough started':'Fetching event batch',preview?'Fictional events and illustrative decisions':config.dataSource==='ems'?'EMS adapter · GET /v1/events':'Bundled fictional event inputs');if(!preview)await loadEvents(signal);const batch=selectedEvents();if(!batch.length)throw Error('No events are available for the selected sources.');currentRun.total=batch.length;flowState.total=batch.length;addLog(`${batch.length} events queued`,`${batch.filter(e=>e.analyst_label).length} have analyst labels; classifier cannot see them`,'done');render();
    for(let i=0;i<batch.length;i++){if(signal.aborted)break;const event=batch[i],started=performance.now();selectedID=event.id;flowState={stage:'retrieve',index:i,completed:i,total:batch.length,eventID:event.id,contexts:[]};let result={event,contexts:[],decision:null,judge:null,ragas:null,tokens:0,timings:{},threshold:config.confidenceThreshold};addLog(`${event.id} · retrieving context`,preview?'Example retrieval fixture':config.mode==='existing'?'Original EMS evidence':`Requested top ${config.topK}`);
      try{const contexts=preview?(event.contexts||[]).slice(0,config.topK):await retrieve(event,signal);if(!contexts.length)throw Error('No contexts returned. This event needs review before classification.');result.contexts=contexts;result.retrieval=retrievalMetrics(event,contexts,!preview&&config.mode==='existing'?contexts.length:config.topK);result.timings.retrieval=Math.round(performance.now()-started);flowState.contexts=contexts;updateLive();if(preview)await delay(reducedMotion?100:650,signal);addLog(`${contexts.length} evidence chunks available`,contexts.map(c=>c.id).join(' · '),'done');flowState.stage='classify';const classifyStarted=performance.now();updateLive();
        if(preview){addLog(`${event.id} · example TP / FP decision`,'Walkthrough playback · no OpenAI request');await delay(reducedMotion?100:1100,signal);const source=walkthroughDecisions[exampleEvents.findIndex(e=>e.id===event.id)];result.decision={...source,cited_context_ids:source.cited_context_ids.filter(id=>contexts.some(c=>c.id===id))};result.model='Illustrative walkthrough';}else if(config.mode==='existing'){if(!event.decision)throw Error('The EMS event has no existing decision. Choose Re-run OpenAI classifier or return decision fields from the adapter.');result.decision=validateDecision(event.decision,contexts);result.model=event.decision.model||'EMS model';addLog(`${event.id} · existing EMS decision`,result.decision.verdict);}else{addLog(`${event.id} · requesting classification`,config.classifierModel);const data=await jsonFetch('/api/classify',{method:'POST',headers:{'Content-Type':'application/json','X-OpenAI-Key':secrets.apiKey},signal,body:JSON.stringify({event,contexts,policy:config.policy,model:config.classifierModel})});result.decision=validateDecision(data.result,contexts);result.model=data.model;result.tokens+=data.tokens||0;connectionVerified=true;}
        result.timings.classification=Math.round(performance.now()-classifyStarted);addLog(`${result.decision.verdict} · ${pct(result.decision.confidence)} confidence`,result.decision.insufficient_evidence?'Insufficient evidence · analyst review required':'Decision received; beginning evaluation','done');flowState.stage='evaluate';flowState.verdict=result.decision.verdict;const evaluationStarted=performance.now();updateLive();
        if(preview){await delay(reducedMotion?100:700,signal);result.judge=validateJudge(walkthroughJudge(event,contexts,result.decision),contexts,event);addLog(`${event.id} · example evidence score`,`${num(result.judge.evidence_support)} · illustrative value`,'done');}else{
          if(config.judge)try{addLog(`${event.id} · judging retrieval + grounding`,config.judgeModel);const data=await jsonFetch('/api/judge',{method:'POST',headers:{'Content-Type':'application/json','X-OpenAI-Key':secrets.apiKey},signal,body:JSON.stringify({event,contexts,decision:result.decision,model:config.judgeModel})});result.judge=validateJudge(data.result,contexts,event);result.tokens+=data.tokens||0;addLog(`Evidence support ${num(result.judge.evidence_support)}`,`${result.judge.claims.length} claims assessed`,'done');}catch(e){if(signal.aborted)throw e;result.evaluationError=e.message;addLog('LLM evaluation failed',e.message,'error');}
          if(config.ragas)try{addLog(`${event.id} · running native RAGAS`,'Faithfulness · context recall · factual correctness');result.ragas=await scoreRagas(event,contexts,result.decision,signal);addLog(`RAGAS faithfulness ${num(result.ragas.faithfulness?.value)}`,event.reference_explanation?'Reference metrics also evaluated':'Reference metrics skipped: no analyst explanation','done');}catch(e){if(signal.aborted)throw e;result.evaluationError=[result.evaluationError,e.message].filter(Boolean).join(' ');addLog('RAGAS evaluation failed',e.message,'error');}
        }
        result.timings.evaluation=Math.round(performance.now()-evaluationStarted);if(event.analyst_label)addLog(`${event.id} · analyst comparison`,result.decision.verdict===event.analyst_label?'Decision matches analyst label':'Decision differs from analyst label',result.decision.verdict===event.analyst_label?'done':'error');else addLog(`${event.id} · no analyst label`,'Excluded from precision, recall, F1, and accuracy');
      }catch(e){if(signal.aborted){if(result.decision){result.evaluationError='Stopped before all evaluation checks completed.';result.latency_ms=Math.round(performance.now()-started);currentRun.results.push(result);}break;}result.error=e.message;addLog(`${event.id} · failed`,e.message,'error');}
      result.latency_ms=Math.round(performance.now()-started);currentRun.results.push(result);flowState.stage='complete';flowState.completed=currentRun.results.length;updateLive();const node=$(`#${result.decision?.verdict==='TP'?'tp':'fp'}-node`);node?.classList.remove('flash');requestAnimationFrame(()=>node?.classList.add('flash'));if(preview)await delay(reducedMotion?100:350,signal);
    }
    currentRun.status=signal.aborted?'cancelled':currentRun.results.some(r=>r.error||r.evaluationError)?'completed_with_errors':'completed';
  }catch(e){currentRun.status=signal.aborted?'cancelled':'failed';if(!signal.aborted){currentRun.error=e.message;addLog('Run failed',e.message,'error');toast(e.message);}}
  finally{running=false;clearInterval(elapsedTimer);currentRun.ended_at=Date.now();flowState.stage='idle';addLog(currentRun.status==='cancelled'?'Run stopped':currentRun.status==='failed'?'Run failed':'Run finished',`${currentRun.results.length} / ${currentRun.total} events processed`,currentRun.status==='completed'?'done':'');history.unshift(currentRun);history=history.slice(0,20);render();announce(`${preview?'Walkthrough':'Evaluation'} ${currentRun.status}. ${currentRun.results.length} events processed.`);}
}
function exportRun(){if(!currentRun)return;const data=safeExport(currentRun),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${currentRun.id}${currentRun.preview?'-example':''}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Run exported with event evidence, settings, and results.');}
async function syncEvents(){if(running)return;try{await loadEvents();selectedID=events[0]?.id;flowState.contexts=[];flowState.eventID=null;currentRun=null;logs=[];render();toast(`${events.length} events loaded.`);}catch(e){toast(e.message);}}
document.addEventListener('click',async event=>{const b=event.target.closest('button,a');if(!b)return;if(b.dataset.page){event.preventDefault();navigate(b.dataset.page);return;}if(b.dataset.event){inspectEvent(b.dataset.event);return;}if(b.dataset.metric){metricDialog(b.dataset.metric);return;}if(b.dataset.contextIndex!=null){scanTick=Number(b.dataset.contextIndex)*4;updateScanner();return;}if(b.dataset.history!=null){if(running){toast('Finish or stop the current run before opening a previous run.');return;}currentRun=history[Number(b.dataset.history)];Object.assign(config,currentRun.config);events=currentRun.results.map(r=>r.event);const last=currentRun.results.at(-1);flowState={stage:'idle',eventID:last?.event.id,contexts:last?.contexts||[],verdict:last?.decision?.verdict};logs=currentRun.logs;page='results';render();return;}const action=b.dataset.action;if(!action)return;if(action==='toggle-config'){configExpanded=!configExpanded;render();}else if(action==='connections'){if(running){toast('Stop or finish the current run before changing connections.');return;}connectionDialog();}else if(action==='close')closeDialog();else if(action==='save-connections')saveConnections();else if(action==='test-openai')await testOpenAI();else if(action==='clear-key'){secrets.apiKey='';connectionVerified=false;$('#api-key').value='';$('#openai-status').textContent='Session key cleared.';updateHeader();}else if(action==='guide')guide();else if(action==='motion'){reducedMotion=!reducedMotion;setMotion();try{localStorage.setItem('axiom-reduce-motion',String(reducedMotion));}catch{}toast(reducedMotion?'Motion reduced. All progress remains visible.':'Motion enabled.');}else if(action==='run')await startRun(false);else if(action==='walkthrough')await startRun(true);else if(action==='cancel'){controller?.abort();toast('Stopping the current request. Completed results are preserved.');}else if(action==='export')exportRun();else if(action==='sync')await syncEvents();});
document.addEventListener('change',event=>{const el=event.target;if(running&&['data-source','batch-limit','top-k','run-mode','judge-enabled','ragas-enabled'].includes(el.id))return;if(el.id==='data-source'){config.dataSource=el.value;events=config.dataSource==='example'?exampleEvents.map(normalizeEvent):[];currentRun=null;logs=[];flowState={stage:'idle',eventID:null,contexts:[]};saveSettings();render();}else if(el.name==='source'){if(running)return;config.sources=$$('input[name="source"]:checked').map(x=>x.value);render();}else if(el.id==='batch-limit'){config.limit=Number(el.value);render();}else if(el.id==='run-mode'){config.mode=el.value;render();}else if(el.id==='judge-enabled'){config.judge=el.checked;render();}else if(el.id==='ragas-enabled'){config.ragas=el.checked;render();if(config.ragas&&!config.ragasURL)toast('Connect the RAGAS Python runner in service settings.');}else if(el.id==='event-filter'){eventFilter=el.value;render();}});
document.addEventListener('input',event=>{if(event.target.id==='top-k'){config.topK=Number(event.target.value);$('#k-value').textContent=config.topK.toString().padStart(2,'0');flowState.contexts=[];updateLive();}if(event.target.id==='event-search'){eventSearch=event.target.value;const start=event.target.selectionStart;render();const input=$('#event-search');input.focus({preventScroll:true});input.setSelectionRange(start,start);}});
$('#dialog').addEventListener('cancel',event=>{event.preventDefault();closeDialog();});$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
window.addEventListener('beforeunload',e=>{if(running){e.preventDefault();e.returnValue='';}});
icons();setMotion();if(config.dataSource==='ems')events=[];render();

function eventMetricDetails(r,e){const j=r?.judge,ret=r?.retrieval;return `<h3 class="guide-heading">Context Relevance · ${pct(j?.context_relevance)}</h3>${j?.context_verdicts?.map(v=>`<div class="claim ${v.relevant?'':'unsupported'}"><span>${v.relevant?'Relevant':'Not relevant'}</span><div>${escapeHTML(v.context_id)}<p class="field-help">${escapeHTML(v.reason)}</p></div></div>`).join('')||'<p class="field-help">No context relevance judgments yet.</p>'}<h3 class="guide-heading">Context Sufficiency (Recall) · ${pct(j?.context_sufficiency)}</h3>${j?.reference_claims?.length?j.reference_claims.map(c=>`<div class="claim ${c.covered?'':'unsupported'}"><span>${c.covered?'Covered':'Missing'}</span><div>${escapeHTML(c.text)}<p class="field-help">${escapeHTML(c.reason)}</p></div></div>`).join(''):'<p class="field-help">Requires an analyst reference explanation and evaluator.</p>'}<h3 class="guide-heading">Precision@k / Recall@k</h3><p class="detail-text">${ret?.hits!=null?`${ret.hits} relevant hits · k = ${ret.k} · ${ret.referenceCount} known relevant chunks<br>Precision@k ${pct(ret.precision)} · Recall@k ${pct(ret.recall)}`:'Requires a complete relevant_context_ids set from your adapter.'}</p><h3 class="guide-heading">Answer Correctness</h3><p class="detail-text">${r?.decision&&e.analyst_label?(r.decision.verdict===e.analyst_label?'Correct':'Incorrect')+' · compared with analyst '+e.analyst_label:'Not scored · requires a decision and analyst label.'}</p>`;}
setInterval(()=>{if(!document.hidden&&!reducedMotion&&!$('#dialog').open)updateScanner(true);},1000);
document.addEventListener('visibilitychange',()=>document.body.classList.toggle('motion-suspended',document.hidden));
window.matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',event=>{reducedMotion=event.matches;setMotion();});
